#include <iostream>
using namespace std;

void insert(int heap[], int& size, int value) {
    int child = size;
    heap[child] = value;
    size++;
    while (child > 0) {
        int parent = (child - 1) / 2;
        if (heap[parent] >= heap[child]) {
            break;
        }
        swap(heap[parent], heap[child]);
        child = parent;
    }
}

int main() {
    int heap[8];
    int size = 0;
    insert(heap, size, 40);
    insert(heap, size, 20);
    insert(heap, size, 30);
    insert(heap, size, 50);
    for (int i = 0; i < size; i++) {
        cout << heap[i] << " ";
    }
    cout << endl;
    return 0;
}
